    impl Event {
        #[allow(unused_variables)]
        pub fn parse(opcode: u16, r: &mut MessageReader<'_>, objects: &mut ObjectMap) -> Result<Event, WireError> {
            match opcode {
                0 => {
                    let format = crate::wayland::protocols::wl_shm::Format(r.uint()?);
                    Ok(Event::Format { format })
                }
                _ => Err(WireError::UnknownOpcode { interface: Interface::WlShm, opcode }),
            }
        }
    }

    /// Opcodes of events after which the object is destroyed by the compositor.
    pub const DESTRUCTOR_EVENTS: &[u16] = &[];

    /// Request names, by opcode.
    pub const REQUESTS: &[&str] = &["create_pool", "release"];

    /// Event names, by opcode.
    pub const EVENTS: &[&str] = &["format"];

    /// wl_shm error values
    ///
    /// These errors can be emitted in response to wl_shm requests.
    #[derive(Clone, Copy, PartialEq, Eq, Hash)]
    pub struct Error(pub u32);

    impl Error {
        /// buffer format is not known
        pub const INVALID_FORMAT: Error = Error(0);
        /// invalid size or stride during pool creation
        pub const INVALID_STRIDE: Error = Error(1);
        /// mmapping the file descriptor failed
        pub const INVALID_FD: Error = Error(2);
    }

    impl std::fmt::Debug for Error {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            match self.0 {
                0 => f.write_str("INVALID_FORMAT"),
                1 => f.write_str("INVALID_STRIDE"),
                2 => f.write_str("INVALID_FD"),
                v => write!(f, "Error({v})"),
            }
        }
    }

